<script setup lang="ts">
import type {ReadingRequest} from '../lib/readerContext'
import {computed,ref} from 'vue'
import {useBackendStore,errorText} from '../stores/backend'
import {useResearchStore} from '../stores/research'
import {useCopilotStore} from '../stores/copilot'
import {backendApi,type BackendMessage} from '../services/backendApi'
import {messageContext} from '../lib/composerContext'
import Icon from './AppIcon.vue'
import Markdown from './ResearchMarkdown.vue'
import CitationCard from './PdfCitationCard.vue'
const props=defineProps<{reading?:boolean}>(),emit=defineEmits<{locate:[value:ReadingRequest];save:[value:BackendMessage]}>()
const backend=useBackendStore(),research=useResearchStore(),copilot=useCopilotStore(),error=ref(''),saving=ref('')
const displayMessages=computed(()=>backend.messages.map(message=>{const parsed=messageContext(message.content);const original=message.role==='assistant'?backend.messages.find(m=>m.runId===message.runId&&m.role==='user'):message;return{...message,display:parsed.text,context:original?messageContext(original.content).context:null}}))
async function copy(text:string){try{await navigator.clipboard.writeText(text);research.notify('回答已复制。')}catch{error.value='浏览器未允许复制，请选择文字后复制。'}}
async function save(message:BackendMessage){if(props.reading){emit('save',message);return}if(saving.value)return;error.value='';saving.value=message.id;try{const original=backend.messages.find(m=>m.runId===message.runId&&m.role==='user'),context=original?messageContext(original.content).context:null;const body=message.content+'\n\n模型任务：'+message.runId+'\n来源快照（仅代表生成时提供范围，不证明模型结论）：\n'+(context?.sources.map(s=>'• '+s.name+' · '+s.scope+' · 资源 '+s.id+(s.versionId?' · 版本 '+s.versionId:'')).join('\n')||'历史消息未记录来源，不补造页码');if(body.length>12000)throw new Error('回答加来源超过笔记 12000 字符限制，请复制后分段整理。');await backendApi.saveNote(backend.conversationId,{title:'AI 回答 · '+(original?messageContext(original.content).text.slice(0,60):'科研对话'),body},'message-note-'+message.runId);await copilot.refreshNotes();research.notify('回答与生成时的来源范围已保存。')}catch(e){error.value=errorText(e)}finally{saving.value=''}}
</script>
<template><div class="backend-conversation copilot-messages"><div v-for="message in displayMessages" :key="message.id" class="chat-message" :class="message.role"><div class="message-label"><Icon v-if="message.role==='assistant'" name="Sparkles" :size="14"/><span>{{message.role==='user'?'你':'Orbit'}}</span></div><CitationCard v-for="block in (reading&&message.role==='user'?message.execution?.reading?.evidence||[]:[])" :key="message.id+block.chunkId" :source="message.execution!.reading!" :block="block" :title="message.context?.sources.find(s=>s.kind==='paper')?.name||'论文原文'" @locate="emit('locate',$event)"/><Markdown v-if="message.display" :text="message.display"/><p v-else>{{backend.busy&&message.runId===backend.run?.id?'正在等待模型…':'本次未返回文字。'}}</p><div v-if="message.role==='user'&&message.context" class="message-reference-chips"><span>{{message.execution?.skill?.primary?.name||message.context.skillName||message.context.skill}}</span><span v-for="source in message.context.sources" :key="source.kind+source.id" :title="source.scope">{{source.name}}</span></div><div v-if="message.role==='assistant'&&message.content" class="message-actions"><button class="text-button" :aria-label="'复制回答 '+message.id" @click="copy(message.content)"><Icon name="Copy" :size="13"/>复制</button><button v-if="!backend.busy" class="text-button" :disabled="!!saving" @click="save(message)">保存笔记</button><template v-if="reading&&message.execution?.reading?.evidence?.length"><button v-for="e in message.execution.reading.evidence" :key="e.chunkId" class="text-button" @click="emit('locate',{...message.execution!.reading!,evidence:[e]})">原文 · PDF 第 {{e.pageIndex+1}} 页</button></template><details><summary>查看来源</summary><small>生成时的提供范围，模型归纳仍需核验。</small><p v-if="message.execution?.skill?.primary">执行能力：{{message.execution.skill.primary.name}} · v{{message.execution.skill.primary.version}}<br/>模型：{{message.execution.model?.model}} · 请求思考：{{message.execution.model?.requestedReasoning||'供应商默认'}}</p><template v-if="message.context?.sources.length"><p v-for="source in message.context.sources" :key="source.kind+source.id"><strong>{{source.name}}</strong><br/>{{source.scope}}<br/><small v-if="source.versionId">版本：{{source.versionId}}</small></p></template><p v-else>本次未记录具体来源；不能据此宣称已读论文全文。页码与原文定位请查看结构化分析的证据。</p></details></div></div><details v-if="backend.skillCalls.length" class="skill-call-list"><summary>本次使用的 Skill（{{backend.skillCalls.length}}）</summary><p v-for="skill in backend.skillCalls" :key="skill">{{skill}}</p></details><p v-if="backend.runError||error" class="form-error" role="alert">{{error||backend.runError}}</p><span v-if="backend.run?.status==='cancelled'" class="settings-hint" role="status">任务已停止，已生成内容保留。</span></div></template>